node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get user details
const user = db.prepare(\"SELECT * FROM users WHERE email = 'maya.chen@example.com'\").get();
console.log('User ID:', user.user_id);
console.log('Name:', user.name);

// Get order - try with # prefix pattern used by tau2Retail
const order = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%CCC96C%'\").get();
console.log('\nOrder:', JSON.stringify(order, null, 2));

// Get order items
if (order) {
  const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = ?\").all(order.order_id);
  console.log('\nOrder Items:', JSON.stringify(items, null, 2));

  const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = ?\").all(order.order_id);
  console.log('\nPayments:', JSON.stringify(payments, null, 2));

  const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = ?\").all(order.order_id);
  console.log('\nFulfillments:', JSON.stringify(fulfillments, null, 2));
}
"

