const db = require('better-sqlite3')('/workspace/world.db');

// Cancel the order
db.prepare(\"UPDATE orders SET status = 'cancelled', cancel_reason = 'no longer needed' WHERE order_id = 'ORD-CCC96C'\").run();

// Cancel each item
db.prepare(\"UPDATE order_items SET item_status = 'cancelled' WHERE order_id = 'ORD-CCC96C'\").run();

// Verify the update
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-CCC96C'\").get();
console.log('Updated Order:', JSON.stringify(order, null, 2));

const items = db.prepare(\"SELECT oi_id, name, quantity, unit_price, item_status FROM order_items WHERE order_id = 'ORD-CCC96C'\").all();
console.log('\nUpdated Items:', JSON.stringify(items, null, 2));
"

